/**
 * Attach a ServiceNow custom event listener to an element
 * Works for React, Vue, Svelte - same pattern everywhere.
 *
 * @param {HTMLElement} element - The DOM element to attach the listener to
 * @param {string} eventName - The ServiceNow event name (use ServiceNowEvents constants)
 * @param {Function} handler - The event handler function
 * @returns {Function} Cleanup function to remove the listener
 */
function attachServiceNowEvent(element, eventName, handler) {
 if (!element || !eventName || !handler) {
 console.warn('[ServiceNow Events] Invalid parameters:', {
 element,
 eventName,
 handler
 });
 return () => { };
 }
 element.addEventListener(eventName, handler);
 return () => {
 element.removeEventListener(eventName, handler);
 };
}

export { ServiceNowEvents, attachServiceNowEvent };
