","import { useEffect } from 'react';
import { attachServiceNowEvent } from './events.js';

/**
 * Helper hook to attach ServiceNow event listeners to an element
 */
const useServiceNowEvent = (elementRef, eventName, handler) => {
 useEffect(() => {
 if (!elementRef.current || !handler)
 return;
 const cleanup = attachServiceNowEvent(elementRef.current, eventName, handler);
 return cleanup;
 }, [elementRef, eventName, handler]);
};

export { useServiceNowEvent };
